export function resolveLocalizedText(textKey) {
  const entry = LOCALIZATION_CATALOG[textKey];
  if (!entry) throw new Error(`Missing canonical localization text_key: ${textKey}`);
  return entry.displayPolicy === "nl_only_artifact"
    ? { nl: entry.nl, displayPolicy: entry.displayPolicy }
    : { nl: entry.nl, zh: entry.zh, displayPolicy: entry.displayPolicy };
}
